#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    long long days;
    scanf("%d %lld", &n, &days);
    vector<long long> bucket(10001, 0);
    long long total = 0;
    int top = 0;
    for (int i = 0; i < n; i++) {
        int w;
        scanf("%d", &w);
        bucket[w]++;
        total += w;
        top = max(top, w);
    }
    // Always halve a piece from the heaviest non-empty bucket.
    for (long long t = 0; t < days; t++) {
        while (top > 1 && bucket[top] == 0) top--;
        if (top == 1) break;
        bucket[top]--;
        int v = (top + 1) / 2;
        bucket[v]++;
        total -= top - v;
    }
    printf("%lld\n", total);
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long days = nextLong();
        long[] bucket = new long[10001];
        long total = 0;
        int top = 0;
        for (int i = 0; i < n; i++) {
            int w = (int) nextLong();
            bucket[w]++;
            total += w;
            top = Math.max(top, w);
        }
        // Always halve a piece from the heaviest non-empty bucket.
        for (long t = 0; t < days; t++) {
            while (top > 1 && bucket[top] == 0) top--;
            if (top == 1) break;
            bucket[top]--;
            int v = (top + 1) / 2;
            bucket[v]++;
            total -= top - v;
        }
        System.out.println(total);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int64 {
	var n int64
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n := int(readInt())
	days := readInt()
	bucket := make([]int64, 10001)
	var total int64
	top := 0
	for i := 0; i < n; i++ {
		w := int(readInt())
		bucket[w]++
		total += int64(w)
		if w > top {
			top = w
		}
	}
	// Always halve a piece from the heaviest non-empty bucket.
	for t := int64(0); t < days; t++ {
		for top > 1 && bucket[top] == 0 {
			top--
		}
		if top == 1 {
			break
		}
		bucket[top]--
		v := (top + 1) / 2
		bucket[v]++
		total -= int64(top - v)
	}
	fmt.Println(total)
}
